package com.aoo.bcg.common.concurrency;import org.junit.jupiter.api.Test;import java.util.concurrent.atomic.AtomicReference;import static org.junit.jupiter.api.Assertions.*;
class EventLoopBlockingGuardTest{@Test void blockingAdapterFailsOnEventLoopBeforeCallingResource(){var called=new AtomicReference<>(false);assertThrows(IllegalStateException.class,()->EventLoopBlockingGuard.eventLoop(()->{try{EventLoopBlockingGuard.blocking(()->{called.set(true);return 1;});}catch(RuntimeException e){throw e;}catch(Exception e){throw new RuntimeException(e);}}).run());assertFalse(called.get());}}
